// Collect Organization Pages
// Validates every Pipedrive page (success flag, data array) and fails the run
// on any malformed page. Pages are sorted by update_time, so a page cap
// (PIPEDRIVE_MAX_PAGES_PER_ENTITY) leaves a consistent prefix: the backlog is
// picked up by the next incremental run.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const ENTITY = 'organizations';
const PREV = null;
const pages = $input.all().map((i) => i.json);
const prev = PREV ? $(PREV).first().json : { extract: {}, truncated: {}, pageCounts: {} };
const byId = new Map();
for (const [i, p] of pages.entries()) {
  if (!p || p.success !== true || !Array.isArray(p.data)) throw new Error(`Pipedrive ${ENTITY} page ${i + 1} is malformed or unsuccessful (${p && p.error ? String(p.error).slice(0, 120) : 'no success flag'}); nothing written.`);
  for (const r of p.data) {
    if (!r || !Number.isInteger(r.id)) throw new Error(`Pipedrive ${ENTITY} page ${i + 1} contains a record without an integer id; nothing written.`);
    const old = byId.get(r.id);
    if (!old || String(r.update_time) >= String(old.update_time)) byId.set(r.id, r);
  }
}
const last = pages[pages.length - 1] || {};
const nextCursor = last.additional_data && last.additional_data.next_cursor;
const truncated = !!nextCursor && pages.length >= config.pipedrive.maxPages;
if (nextCursor && !truncated) throw new Error(`Pipedrive ${ENTITY} pagination stopped early with a next_cursor; nothing written.`);
return [{ json: {
  source: 'pipedrive',
  extract: { ...prev.extract, [ENTITY]: [...byId.values()] },
  truncated: { ...prev.truncated, [ENTITY]: truncated },
  pageCounts: { ...prev.pageCounts, [ENTITY]: pages.length },
} }];

