  if (a.locality) rec.properties.city = clean(a.locality);
  if (a.country) rec.properties.country = clean(a.country);
  if (a.postal_code) rec.properties.zip = clean(a.postal_code);
  const domainField = (src.mappingOverride && src.mappingOverride.orgDomainField) || config.pipedrive.orgDomainField;
  if (domainField) {
    const raw = r.custom_fields && r.custom_fields[domainField];
    const d = String((raw && raw.value) || raw || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');
    if (d && /^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(d)) rec.properties.domain = d;
    else if (d) rec.issues.push({ code: 'ORG_INVALID_DOMAIN', severity: 'warning', detail: 'Website/domain value is not a valid domain; omitted' });
