  let first = clean(r.first_name), last = clean(r.last_name);
  const full = clean(r.name);
  if (!first && !last && full) { const parts = full.split(' '); first = parts.shift(); last = parts.join(' '); }
  if (first) rec.properties.firstname = first;
  if (last) rec.properties.lastname = last;
  const email = primary(r.emails).toLowerCase();
  if (email && EMAIL_RE.test(email)) {
    if (seenEmails.has(email)) rec.issues.push({ code: 'DUPLICATE_EMAIL_IN_SOURCE', severity: 'error', detail: `Email also used by Pipedrive person ${seenEmails.get(email)}; HubSpot contact emails are unique` });
