// ---- deals -> deals ---------------------------------------------------------------------
for (const r of src.extract.deals || []) {
  const rec = base('deals', r, 'deals');
  const title = clean(r.title);
  if (!title) rec.issues.push({ code: 'DEAL_MISSING_TITLE', severity: 'error', detail: 'Deal has no title' });
  rec.properties.dealname = title;
  if (r.value !== null && r.value !== undefined && r.value !== '') {
    const n = Number(r.value);
    if (Number.isFinite(n) && n >= 0 && n < 1e15) rec.properties.amount = String(Math.round(n * 100) / 100);
