  const st2 = stage || M.defaultStage;
  if (st2) { rec.properties.pipeline = st2.pipeline; rec.properties.dealstage = st2.dealstage; if (!stage) rec.issues.push({ code: 'DEAL_DEFAULT_STAGE_USED', severity: 'warning', detail: `Stage ${r.stage_id} unmapped; DEFAULT_DEAL_STAGE used` }); }
  else rec.issues.push({ code: 'DEAL_UNMAPPED_STAGE', severity: 'error', detail: `Pipedrive stage ${r.stage_id} (${r.status}) has no STAGE_MAP_JSON entry` });
  const close = iso(r.won_time || r.lost_time || r.close_time) || iso(r.expected_close_date);
  if (close) rec.properties.closedate = close;
  const org = fkId(r.org_id), per = fkId(r.person_id);
  if (org) rec.refs.organizations = String(org);
  if (per) rec.refs.persons = String(per);
