  records.push(rec);
}
// ---- activities -> calls / meetings / tasks ----------------------------------------------
for (const r of src.extract.activities || []) {
  const type = String(r.type || '').toLowerCase();
  // An activity keeps the HubSpot object type it was first migrated as, so a
  // later Pipedrive change (e.g. a planned call marked done) cannot create a
  // second record in another object type. Open calls become CALL tasks
  // because HubSpot calls have no "scheduled" status.
  const pinned = state.maps.activities[String(r.id)] && state.maps.activities[String(r.id)].t;
  let objectType = pinned || M.activityTypeMap[type] || 'tasks';
  if (!pinned && objectType === 'calls' && !r.done) objectType = 'tasks';
  const rec = base('activities', r, objectType);
  if (!M.activityTypeMap[type]) rec.issues.push({ code: 'ACTIVITY_TYPE_DEFAULTED', severity: 'warning', detail: `Activity type "${type.slice(0, 40)}" unmapped; migrated as a task` });
  const subject = clean(r.subject) || `Pipedrive ${type || 'activity'} ${r.id}`;
  const body = clean(r.note || r.public_description || '');
  let ts = iso(r.due_date ? `${r.due_date}${r.due_time ? 'T' + String(r.due_time).slice(0, 5) + ':00Z' : ''}` : null);
  if (!ts) { ts = iso(r.add_time); if (ts) rec.issues.push({ code: 'ACTIVITY_NO_DUE_DATE', severity: 'warning', detail: 'No valid due date; add_time used as timestamp' }); }
  if (!ts) rec.issues.push({ code: 'ACTIVITY_INVALID_DATE', severity: 'error', detail: 'No valid due date or add time' });
  else rec.properties.hs_timestamp = ts;
  const durMin = (() => { const m = String(r.duration || '').match(/^(\d{1,2}):(\d{2})/); return m ? Number(m[1]) * 60 + Number(m[2]) : 0; })();
  if (objectType === 'calls') { rec.properties.hs_call_title = subject; if (body) rec.properties.hs_call_body = body; rec.properties.hs_call_status = r.done ? 'COMPLETED' : 'QUEUED'; if (durMin) rec.properties.hs_call_duration = String(durMin * 60000); }
  else if (objectType === 'meetings') { rec.properties.hs_meeting_title = subject; if (body) rec.properties.hs_meeting_body = body; if (ts) { rec.properties.hs_meeting_start_time = ts; rec.properties.hs_meeting_end_time = new Date(Date.parse(ts) + (durMin || 30) * 60000).toISOString(); } rec.properties.hs_meeting_outcome = r.done ? 'COMPLETED' : 'SCHEDULED'; }
  else { rec.properties.hs_task_subject = subject; if (body) rec.properties.hs_task_body = body; rec.properties.hs_task_status = r.done ? 'COMPLETED' : 'NOT_STARTED'; rec.properties.hs_task_type = type === 'email' ? 'EMAIL' : type === 'call' ? 'CALL' : 'TODO'; }
  const d = fkId(r.deal_id), p = fkId(r.person_id), o = fkId(r.org_id);
  if (d) rec.refs.deals = String(d);
  if (p) rec.refs.persons = String(p);
  if (o) rec.refs.organizations = String(o);
  if (!d && !p && !o) rec.issues.push({ code: 'ACTIVITY_NO_PARENT', severity: 'warning', detail: 'Activity is not linked to a deal, person or organization' });
