return [{ json: {
  source: src.source,
  state,
  stateSource: st.stateSource,
  requests: st.requests,
  truncated: src.truncated,
  pageCounts: src.pageCounts,
  hubspotExisting: src.hubspotExisting || null,
  records,
  extractedCounts: Object.fromEntries(Object.entries(src.extract).map(([k, v]) => [k, v.length])),
  maxUpdateTime: Object.fromEntries(Object.entries(src.extract).map(([k, v]) => [k, v.reduce((m, r) => (String(r.update_time) > m ? String(r.update_time) : m), '')])),
} }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Build Preflight Lookups  (read-only)
// HubSpot batch reads by unique property for:
//   * records not yet in the local ID mapping table (create vs update),
//   * foreign keys pointing outside this extract (FK resolution),
//   * targets of pending associations from earlier runs,
//   * every contact email (conflicts with contacts created outside the
//     migration, since HubSpot contact emails are unique).
// Emits one item per batch read, or a single { noop: true } item.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const b = $input.first().json;
const H = config.hubspot;
const maps = b.state.maps;
const TYPE = H.objectTypes;
const inExtract = {};
for (const r of b.records) (inExtract[r.entity] = inExtract[r.entity] || new Set()).add(r.pdId);
const wanted = {}; // `${objectType}|${idProperty}` -> Set(ids)
const want = (objectType, idProperty, id) => { const k = `${objectType}|${idProperty}`; (wanted[k] = wanted[k] || new Set()).add(String(id)); };
const active = b.records.filter((r) => !r.quarantined && config.entities.includes(r.entity));
for (const r of active) {
  if (!maps[r.entity][r.pdId]) {
    if (r.entity === 'activities') for (const t of ['calls', 'meetings', 'tasks']) want(t, r.idProperty, r.pdId);
    else want(r.objectType, r.idProperty, r.pdId);
  }
  for (const [ent, pd] of Object.entries(r.refs)) if (!maps[ent][pd] && !(inExtract[ent] && inExtract[ent].has(pd))) want(TYPE[ent], H.idProps[ent], pd);
  if (r.emailKey) want('contacts', 'email', r.emailKey);
}
for (const p of b.state.pending || []) {
  if (!maps[p.fromEntity][p.fromPd]) { if (p.fromEntity === 'activities') want(p.fromType, H.idProps.activities, p.fromPd); else want(TYPE[p.fromEntity], H.idProps[p.fromEntity], p.fromPd); }
  if (!maps[p.toEntity][p.toPd]) want(TYPE[p.toEntity], H.idProps[p.toEntity], p.toPd);
}
const items = [];
for (const [k, set] of Object.entries(wanted)) {
  const [objectType, idProperty] = k.split('|');
  const ids = [...set].sort();
  for (let i = 0; i < ids.length; i += H.batchSize) {
    const chunk = ids.slice(i, i + H.batchSize);
    const properties = [...new Set([idProperty, ...(objectType === 'contacts' ? ['email', H.idProps.persons] : [])])];
    items.push({ json: {
      mode: config.sandboxMode ? 'simulate' : 'live', objectType, idProperty, ids: chunk,
      url: config.sandboxMode ? null : `${H.base}/crm/v3/objects/${objectType}/batch/read`,
      body: { idProperty, properties, inputs: chunk.map((id) => ({ id })) },
    } });
  }
}
return items.length ? items : [{ json: { noop: true } }];

