// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Collect Preflight Results
// Fails closed if any lookup failed (an incomplete lookup could hide an email
// conflict or a foreign key). Produces:
//   found[objectType][pipedriveId] = HubSpot id
//   emailOwners[email] = { id, pipedriveId }
