  if (reqs.length !== items.length) throw new Error(`Preflight returned ${items.length} responses for ${reqs.length} lookups; nothing written.`);
  const H = $('Config & Safety Gate').first().json.config.hubspot;
  items.forEach((res, i) => {
    const q = reqs[i];
    if (!res || res.error || !Array.isArray(res.results)) throw new Error(`HubSpot preflight lookup failed for ${q.objectType} by ${q.idProperty}: ${res && res.error ? String(res.error.message || res.error).slice(0, 160) : 'unexpected response'}. Nothing written (fail closed).`);
    lookups++;
    for (const r of res.results) {
      const p = r.properties || {};
      if (q.idProperty === 'email') { if (p.email) emailOwners[String(p.email).toLowerCase()] = { id: String(r.id), pipedriveId: p[H.idProps.persons] ? String(p[H.idProps.persons]) : null }; }
