// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Migration Plan & Validation Report
// Classifies every extracted record:
//   CREATE / UPDATE     -> idempotent batch upsert by pipedrive_*_id
//   SKIP_UNCHANGED      -> already migrated with an identical content hash
//   QUARANTINE          -> validation error; never written, listed with reasons
//   SKIP_ENTITY_DISABLED-> entity not in ENTITIES
// Resolves contact email conflicts (CONTACT_EMAIL_CONFLICT_POLICY), plans
// associations from Pipedrive foreign keys, and applies the run guards
// (MAX_WRITES_PER_RUN, MAX_QUARANTINE_PCT). The report is the dry-run output.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const N = $('Normalize & Validate').first().json;
const pre = $input.first().json;
const H = config.hubspot;
const maps = N.state.maps;
const TYPE = H.objectTypes;
const ACT = ['calls', 'meetings', 'tasks'];
function fnv1a(s) { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); }
