const foundId = (objectType, pd) => (pre.found[objectType] || {})[pd] || null;

const writtenInRun = {}; // entity -> Set(pd) planned for write (FK targets resolvable after the write)
const planned = N.records.map((r0) => {
  const r = JSON.parse(JSON.stringify(r0));
  r.action = null; r.mode = 'upsert'; r.existingId = null;
  if (!config.entities.includes(r.entity)) { r.action = 'SKIP_ENTITY_DISABLED'; return r; }
  if (r.quarantined) { r.action = 'QUARANTINE'; return r; }
  const mapped = maps[r.entity][r.pdId];
  if (mapped) r.existingId = String(mapped.id);
  else if (r.entity === 'activities') {
    const hit = ACT.find((t) => foundId(t, r.pdId));
    if (hit && hit !== r.objectType) { r.issues.push({ code: 'ACTIVITY_TYPE_MISMATCH_EXISTING', severity: 'error', detail: `Already exists in HubSpot as ${hit} ${foundId(hit, r.pdId)}, planned as ${r.objectType}` }); r.action = 'QUARANTINE'; r.quarantined = true; return r; }
    if (hit) r.existingId = foundId(hit, r.pdId);
  } else r.existingId = foundId(r.objectType, r.pdId);
  if (r.entity === 'persons' && r.emailKey) {
    const owner = pre.emailOwners[r.emailKey];
    if (owner && owner.pipedriveId !== r.pdId && owner.id !== r.existingId) {
      const policy = config.mapping.emailConflictPolicy;
      if (policy === 'strip_email') {
        delete r.properties.email;
        r.issues.push({ code: 'CONTACT_EMAIL_STRIPPED', severity: 'warning', detail: `Email belongs to HubSpot contact ${owner.id}; migrated without email` });
        r.hash = fnv1a(stable(r.properties) + '|' + stable(r.refs) + '|' + r.objectType);
      } else if (policy === 'adopt' && !r.existingId && !owner.pipedriveId) {
        r.mode = 'update'; r.existingId = owner.id;
        r.issues.push({ code: 'CONTACT_ADOPTED_BY_EMAIL', severity: 'warning', detail: `Existing HubSpot contact ${owner.id} with the same email is adopted and tagged with the Pipedrive id` });
      } else {
        r.issues.push({ code: 'CONTACT_EMAIL_CONFLICT', severity: 'error', detail: `Email already used by HubSpot contact ${owner.id}${owner.pipedriveId ? ' (Pipedrive person ' + owner.pipedriveId + ')' : ''}` });
        r.action = 'QUARANTINE'; r.quarantined = true; return r;
      }
