// ---- associations planned from foreign keys -------------------------------------------
const intents = [];
const seen = new Set();
const addIntent = (it) => { const k = `${it.fromType}|${it.fromPd}|${it.toType}|${it.toPd}`; if (!seen.has(k)) { seen.add(k); intents.push(it); } };
for (const r of planned) {
  if (!['CREATE', 'UPDATE'].includes(r.action)) continue;
  for (const [ent, pd] of Object.entries(r.refs)) if (config.entities.includes(ent)) addIntent({ fromEntity: r.entity, fromType: r.objectType, fromPd: r.pdId, toEntity: ent, toType: TYPE[ent], toPd: pd });
}
for (const p of N.state.pending || []) addIntent({ fromEntity: p.fromEntity, fromType: p.fromType, fromPd: p.fromPd, toEntity: p.toEntity, toType: p.toType, toPd: p.toPd, fromPending: true });
