// ---- report --------------------------------------------------------------------------------
const byEntity = {};
for (const r of planned) {
  const e = (byEntity[r.entity] = byEntity[r.entity] || { extracted: 0, CREATE: 0, UPDATE: 0, SKIP_UNCHANGED: 0, QUARANTINE: 0, SKIP_ENTITY_DISABLED: 0, warnings: 0 });
  e.extracted++; e[r.action]++; e.warnings += r.issues.filter((i) => i.severity === 'warning').length;
}
const issueCounts = {};
for (const r of planned) for (const i of r.issues) issueCounts[i.code] = (issueCounts[i.code] || 0) + 1;
const report = {
  runId: config.runId,
  generatedAt: config.now,
  mode: config.sandboxMode ? 'SANDBOX' : config.dryRun ? 'DRY_RUN' : 'LIVE',
  source: N.source,
  entities: config.entities,
  extractedSince: Object.fromEntries(Object.entries(N.requests).map(([k, v]) => [k, v.since])),
  backlogRemaining: N.truncated,
  summary: byEntity,
  totals: { writes: writes.length, creates: writes.filter((r) => r.action === 'CREATE').length, updates: writes.filter((r) => r.action === 'UPDATE').length, unchanged: planned.filter((r) => r.action === 'SKIP_UNCHANGED').length, quarantined: quarantined.length, quarantinePct: quarantinePct.toFixed(1), associationsPlanned: intents.length, associationsUnresolved: fkUnresolved.length },
  issueCounts,
  quarantine: quarantined.slice(0, 500).map((r) => ({ entity: r.entity, pipedriveId: r.pdId, reasons: r.issues.filter((i) => i.severity === 'error').map((i) => `${i.code}: ${i.detail}`) })),
  warnings: planned.filter((r) => r.issues.some((i) => i.severity === 'warning')).slice(0, 500).map((r) => ({ entity: r.entity, pipedriveId: r.pdId, action: r.action, warnings: r.issues.filter((i) => i.severity === 'warning').map((i) => i.code) })),
  emailConflicts: planned.filter((r) => r.issues.some((i) => /^CONTACT_EMAIL_|^CONTACT_ADOPTED|DUPLICATE_EMAIL/.test(i.code))).map((r) => ({ pipedriveId: r.pdId, codes: r.issues.filter((i) => /EMAIL|ADOPTED/.test(i.code)).map((i) => i.code) })),
  fkUnresolved: fkUnresolved.slice(0, 500),
  plannedWrites: writes.slice(0, 1000).map((r) => ({ entity: r.entity, objectType: r.objectType, pipedriveId: r.pdId, action: r.action, hubspotId: r.existingId, mode: r.mode })),
  proposedWatermarks: N.maxUpdateTime,
  guards: { passed: guardFailures.length === 0, failures: guardFailures },
  configWarnings: config.warnings,
  configErrors: config.configErrors,
  preflightLookups: pre.lookups,
};
const writeBlockers = [...config.writes.blockers, ...guardFailures];
if (!writes.length && !intents.length) writeBlockers.push('Nothing to migrate');
return [{ json: { report, planned, intents, writeAllowed: writeBlockers.length === 0, writeBlockers } }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Dry-Run Validation Report
// Nothing was written and migration state is unchanged. The report lists
// planned creates / updates, unchanged skips, quarantined records with reasons,
// email conflicts, unresolved foreign keys and proposed watermarks.
// ============================================================================
const P = $input.first().json;
return [{ json: { mode: 'dry-run', writeBlockedBy: P.writeBlockers, report: P.report } }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Build Upsert Batches
// Writes in dependency order (companies, contacts, deals, then activities)
// as HubSpot batch upserts keyed by the unique pipedrive_*_id property, so a
// retried or repeated batch updates instead of duplicating. Adopted contacts
// (CONTACT_EMAIL_CONFLICT_POLICY=adopt) use batch update by HubSpot id.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const P = $input.first().json;
const H = config.hubspot;
const ORDER = ['companies', 'contacts', 'deals', 'calls', 'meetings', 'tasks'];
const writes = P.planned.filter((r) => ['CREATE', 'UPDATE'].includes(r.action));
const items = [];
for (const objectType of ORDER) {
  for (const mode of ['upsert', 'update']) {
    const group = writes.filter((r) => r.objectType === objectType && r.mode === mode);
    for (let i = 0; i < group.length; i += H.batchSize) {
      const chunk = group.slice(i, i + H.batchSize);
      const inputs = mode === 'upsert'
        ? chunk.map((r) => ({ idProperty: r.idProperty, id: r.pdId, properties: r.properties }))
        : chunk.map((r) => ({ id: r.existingId, properties: r.properties }));
      items.push({ json: { objectType, mode, entity: chunk[0].entity, pdIds: chunk.map((r) => r.pdId), hsIds: chunk.map((r) => r.existingId), url: `${H.base}/crm/v3/objects/${objectType}/batch/${mode}`, body: { inputs } } });
    }
  }
}
return items.length ? items : [{ json: { noop: true } }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Record Write Results
// Maps each HubSpot batch response back to Pipedrive ids. A failed batch marks
// every record in it as failed (the entity's watermark is then held back so the
// next run retries; upserts make the retry safe). Partial (207) responses mark
// only the records without a result as failed.
// ============================================================================
const reqs = $('Build Upsert Batches').all().map((i) => i.json);
const res = $input.all().map((i) => i.json);
const written = { organizations: {}, persons: {}, deals: {}, activities: {} };
const failures = [];
let batches = 0;
if (!(reqs.length === 1 && reqs[0].noop)) {
  reqs.forEach((q, i) => {
    batches++;
    const r = res[i] || {};
    if (r.error || !Array.isArray(r.results)) {
      const msg = r.error ? String(r.error.message || r.error.description || r.error).slice(0, 300) : 'unexpected response';
      for (const pd of q.pdIds) failures.push({ entity: q.entity, objectType: q.objectType, pipedriveId: pd, error: msg });
      return;
    }
    const got = new Map();
    q.pdIds.forEach((pd, k) => {
      const idProp = q.body.inputs[k].idProperty;
      const hit = q.mode === 'upsert'
        ? r.results.find((x) => x.properties && String(x.properties[idProp]) === pd)
        : r.results.find((x) => String(x.id) === String(q.hsIds[k]));
      if (hit) got.set(pd, hit);
    });
    const errText = Array.isArray(r.errors) && r.errors.length ? r.errors.map((e) => e.message).join('; ').slice(0, 300) : 'no result returned for this record';
    for (const pd of q.pdIds) {
      const hit = got.get(pd);
      if (hit) written[q.entity][pd] = { id: String(hit.id), objectType: q.objectType, created: hit.new === true };
      else failures.push({ entity: q.entity, objectType: q.objectType, pipedriveId: pd, error: errText });
    }
  });
}
return [{ json: { written, failures, batches } }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Build Association Batches
// Resolves every planned association through the ID mapping chain:
//   this run's write results -> persisted mapping table -> preflight lookup.
// Pairs whose endpoint is not in HubSpot yet (quarantined, failed, not yet
// extracted) become PENDING and are retried automatically on later runs.
// Uses the v4 default-association batch endpoint (idempotent).
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const P = $('Migration Plan & Validation Report').first().json;
const N = $('Normalize & Validate').first().json;
const pre = $('Collect Preflight Results').first().json;
let W = { written: { organizations: {}, persons: {}, deals: {}, activities: {} }, failures: [] };
try { W = $('Record Write Results').first().json; } catch (e) { /* no upserts this run */ }
const H = config.hubspot;
const idOf = (ent, pd, type) => {
  const w = W.written[ent] && W.written[ent][pd];
  if (w) return w.id;
  const m = N.state.maps[ent][pd];
  if (m) return String(m.id);
  return (pre.found[type] || {})[pd] || null;
};
const groups = {};
const pending = [];
for (const it of P.intents) {
  const from = idOf(it.fromEntity, it.fromPd, it.fromType);
  const to = idOf(it.toEntity, it.toPd, it.toType);
  if (!from || !to) { pending.push({ ...it, reason: !from ? 'SOURCE_NOT_IN_HUBSPOT' : 'TARGET_NOT_IN_HUBSPOT' }); continue; }
  const k = `${it.fromType}|${it.toType}`;
  (groups[k] = groups[k] || []).push({ ...it, from, to });
}
const items = [];
if (config.writes.associationsEnabled) {
  for (const [k, list] of Object.entries(groups)) {
    const [fromType, toType] = k.split('|');
    for (let i = 0; i < list.length; i += H.assocBatchSize) {
      const chunk = list.slice(i, i + H.assocBatchSize);
      items.push({ json: { fromType, toType, pairs: chunk, url: `${H.base}/crm/v4/associations/${fromType}/${toType}/batch/associate/default`, body: { inputs: chunk.map((p) => ({ from: { id: p.from }, to: { id: p.to } })) } } });
    }
  }
}
return items.length ? items.map((i) => ({ json: { ...i.json, pending } })) : [{ json: { noop: true, pending, disabled: !config.writes.associationsEnabled } }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Record Association Results
// Failed association batches go back to the pending queue for the next run.
// ============================================================================
const reqs = $('Build Association Batches').all().map((i) => i.json);
const res = $input.all().map((i) => i.json);
let created = 0;
const failed = [];
reqs.forEach((q, i) => {
  const r = res[i] || {};
  if (r.error || (r.status && r.status !== 'COMPLETE') || (Array.isArray(r.errors) && r.errors.length)) {
    const msg = r.error ? String(r.error.message || r.error).slice(0, 200) : (r.errors || []).map((e) => e.message).join('; ').slice(0, 200) || 'association batch not complete';
    for (const p of q.pairs) failed.push({ ...p, reason: 'ASSOCIATION_FAILED: ' + msg });
  } else created += q.pairs.length;
});
return [{ json: { created, failed, pending: reqs[0] ? reqs[0].pending : [] } }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Commit Migration State
// Updates the persisted ID mapping tables (Pipedrive id -> HubSpot id + content
// hash), advances each entity's watermark only when that entity had zero write
// failures, stores the pending-association queue and the quarantine registry,
// and appends a run log entry. Persisted only for armed live runs.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const N = $('Normalize & Validate').first().json;
const P = $('Migration Plan & Validation Report').first().json;
let W = { written: { organizations: {}, persons: {}, deals: {}, activities: {} }, failures: [], batches: 0 };
try { W = $('Record Write Results').first().json; } catch (e) { /* no upserts */ }
const AB = $('Build Association Batches').first().json;
let A = { created: 0, failed: [], pending: AB.pending || [] };
try { A = $('Record Association Results').first().json; } catch (e) { /* no association batches */ }
const state = JSON.parse(JSON.stringify(N.state));

const recByKey = new Map(P.planned.map((r) => [`${r.entity}:${r.pdId}`, r]));
let mapped = 0;
for (const [entity, recs] of Object.entries(W.written)) {
  for (const [pd, w] of Object.entries(recs)) {
    const r = recByKey.get(`${entity}:${pd}`);
    state.maps[entity][pd] = entity === 'activities' ? { id: w.id, h: r ? r.hash : '', t: w.objectType } : { id: w.id, h: r ? r.hash : '' };
    delete state.quarantine[`${entity}:${pd}`];
    mapped++;
  }
}
for (const r of P.planned) if (r.action === 'QUARANTINE') state.quarantine[`${r.entity}:${r.pdId}`] = { codes: r.issues.filter((i) => i.severity === 'error').map((i) => i.code), at: config.now, updateTime: r.updateTime };

const failedEntities = new Set(W.failures.map((f) => f.entity));
const watermarkChanges = {};
for (const e of config.entities) {
  const next = N.maxUpdateTime[e];
  if (failedEntities.has(e)) { watermarkChanges[e] = { held: true, reason: 'write failures', value: state.watermarks[e] }; continue; }
  if (next && (!state.watermarks[e] || next > state.watermarks[e])) { watermarkChanges[e] = { from: state.watermarks[e], to: next }; state.watermarks[e] = next; }
}

const seen = new Set();
const pending = [];
for (const p of [...(A.failed || []), ...(A.pending || [])]) {
  const k = `${p.fromType}|${p.fromPd}|${p.toType}|${p.toPd}`;
  if (seen.has(k)) continue;
  seen.add(k);
  pending.push({ fromEntity: p.fromEntity, fromType: p.fromType, fromPd: p.fromPd, toEntity: p.toEntity, toType: p.toType, toPd: p.toPd, reason: p.reason, since: p.since || config.now });
}
let droppedPending = 0;
if (pending.length > config.guards.maxPendingAssociations) { droppedPending = pending.length - config.guards.maxPendingAssociations; pending.sort((a, b) => (a.since < b.since ? 1 : -1)); pending.length = config.guards.maxPendingAssociations; }
state.pending = pending;

const run = { runId: config.runId, at: config.now, writes: Object.values(W.written).reduce((s, m) => s + Object.keys(m).length, 0), failures: W.failures.length, associations: A.created, pending: pending.length, quarantined: P.report.totals.quarantined };
state.runs = [run, ...state.runs].slice(0, 30);
state.updatedAt = config.now;

let persisted = false;
if (config.writes.allowedByConfig) {
  const sd = $getWorkflowStaticData('global');
  sd.migration = state;
  persisted = true;
}
return [{ json: {
  mode: 'migrated',
  written: W.written,
  failures: W.failures,
  associationsCreated: A.created,
  associationFailures: (A.failed || []).length,
  pendingAssociations: pending.length,
  droppedPending,
  mappedRecords: mapped,
  watermarkChanges,
  persisted,
  mapSizes: Object.fromEntries(Object.entries(state.maps).map(([k, v]) => [k, Object.keys(v).length])),
} }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Migration Run Report
// One summary item per execution. No tokens, no record contents.
// ============================================================================
const { config, safetyDecisions } = $('Config & Safety Gate').first().json;
const P = $('Migration Plan & Validation Report').first().json;
const last = $input.first().json;
let status;
if (last.mode === 'migrated') status = last.failures.length || last.associationFailures ? 'PARTIAL' : 'MIGRATED';
else if (P.report.guards.failures.length && config.writes.allowedByConfig) status = 'BLOCKED_BY_GUARD';
else if (P.writeBlockers.includes('Nothing to migrate')) status = 'NOTHING_TO_MIGRATE';
else status = config.sandboxMode ? 'SANDBOX_DRY_RUN' : 'DRY_RUN';
return [{ json: {
  runId: config.runId,
  status,
  mode: P.report.mode,
  entities: config.entities,
  totals: P.report.totals,
  summary: P.report.summary,
  issueCounts: P.report.issueCounts,
  backlogRemaining: P.report.backlogRemaining,
  writes: last.mode === 'migrated' ? { failures: last.failures, associationsCreated: last.associationsCreated, associationFailures: last.associationFailures, pendingAssociations: last.pendingAssociations, watermarkChanges: last.watermarkChanges, mapSizes: last.mapSizes, persisted: last.persisted } : null,
  writeBlockedBy: last.mode === 'migrated' ? [] : P.writeBlockers,
  warnings: config.warnings,
  configErrors: config.configErrors,
  safetyDecisions,
} }];
